# Patch build_s05.py
ba_path = ROOT / ".tools" / "build_s05.py"
ba_text = ba_path.read_text(encoding="utf-8")

for slug, faq in EXPANDED_FAQ.items():
    pattern = r'("slug":\s*"' + re.escape(slug) + r'",.*?"faq":\s*\[)(.*?)(\n\s*\],\s*\n\s*"refs")'
    m = re.search(pattern, ba_text, re.S)
    if not m:
        print(f"  NOT FOUND: {slug}")
        continue
    new_lines = []
    for q, a in faq:
        q_esc = q.replace('"', '\\"')
        a_esc = a.replace('"', '\\"')
        new_lines.append(f'        ("{q_esc}",\n         "{a_esc}"),')
    new_block = "\n" + "\n".join(new_lines)
    new_text = ba_text[:m.start(2)] + new_block + ba_text[m.end(2):]
    if new_text != ba_text:
        ba_text = new_text
        print(f"  patched: {slug}")

ba_path.write_text(ba_text, encoding="utf-8")
print("\nbuild_s05.py FAQ patched.")
